/** Foreground-only sensor check and persisted heuristic sensitivity. Never starts a tracking service. */
public final class MotionSensorActivity extends Activity {
    static MotionPort.Factory ports=MotionPort.PLATFORM;
    private MotionPort port;private MotionSettings.Factory settings;private MotionSettings.Version settingsVersion;private MotionProfile savedProfile=new MotionProfile(1);private final MotionPreview preview=new MotionPreview();private final Handler handler=new Handler(Looper.getMainLooper());
    private int level=1,expected=1;private boolean resumed,registered,unreliable,readFailed,manualSelected;private String failure="",registrationError="",token;private MotionSignalChart chart;private TextView status,help,levelLabel;private Design.Icon resultIcon;private Dialog explanation;private android.graphics.drawable.GradientDrawable statusDot;private Button use;private LinearLayout body;
    private final Runnable tick=new Runnable(){public void run(){update();if(resumed)handler.postDelayed(this,250);}};private final Runnable poll=this::observe;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);port=ports.create(getApplicationContext());settings=MotionSettings.factory;try{SharedPreferences prefs=settings.open(this);settingsVersion=new MotionSettings.Version(prefs);savedProfile=MotionSettings.read(prefs);expected=level=savedProfile.level;}catch(Exception e){readFailed=true;failure=e.getMessage();}if(state!=null){manualSelected=state.getBoolean("manualSelected",false);level=state.getInt("level",level);expected=state.getInt("expected",expected);token=state.getString("token");failure=state.getString("failure",failure);}render();}
    @Override protected void onResume(){super.onResume();resumed=true;test();handler.post(tick);observe();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacksAndMessages(null);port.close();registered=false;super.onPause();}
    private void render(){body=Design.page(this,false,null,n->{});RecordUi.header(body,"Motion sensor",this::back);RecordUi.label(this,body);Design.space(body,12);Design.text(body,"Your phone’s accelerometer measures movement during sleep.",15,400,Design.MUTED);Design.space(body,14);
        LinearLayout illustration=Design.row(this);illustration.setGravity(Gravity.CENTER);Design.Icon phone=new Design.Icon(this,"phone",Design.VIOLET);illustration.addView(phone,new LinearLayout.LayoutParams(Design.dp(this,132),Design.dp(this,90)));body.addView(illustration);Design.space(body,10);
        LinearLayout sensor=Design.row(this);Design.pad(sensor,16,12);sensor.setBackground(Design.shape(this,Design.SOFT,14));sensor.addView(Design.text(this,"Phone accelerometer",14,600,Design.INK),new LinearLayout.LayoutParams(0,-2,1));status=Design.text(this,"",13,500,Design.BROWN);statusDot=Design.shape(this,0xffa29c98,10);statusDot.setBounds(0,0,Design.dp(this,7),Design.dp(this,7));status.setCompoundDrawables(statusDot,null,null,null);status.setCompoundDrawablePadding(Design.dp(this,7));sensor.addView(status);body.addView(sensor);Design.space(body,14);Design.text(body,"Live motion signal",17,600,Design.INK);Design.space(body,5);Design.text(body,"Relative movement · last 15 seconds",12,400,Design.MUTED);Design.space(body,8);chart=new MotionSignalChart(this);body.addView(chart,new LinearLayout.LayoutParams(-1,Design.dp(this,130)));Design.space(body,10);
        LinearLayout result=Design.row(this);Design.pad(result,14,12);result.setBackground(Design.shape(this,Design.SOFT,16));resultIcon=new Design.Icon(this,"check",Design.CREAM);resultIcon.setBackground(Design.shape(this,0xff17833e,20));resultIcon.setPadding(Design.dp(this,5),Design.dp(this,5),Design.dp(this,5),Design.dp(this,5));LinearLayout.LayoutParams checkLayout=new LinearLayout.LayoutParams(Design.dp(this,28),Design.dp(this,28));checkLayout.rightMargin=Design.dp(this,12);result.addView(resultIcon,checkLayout);help=Design.text(this,"",14,500,Design.INK);result.addView(help,new LinearLayout.LayoutParams(0,-2,1));body.addView(result);Design.space(body,14);Design.text(body,"Move phone gently",15,600,Design.INK);Design.space(body,4);Design.text(body,"Try a small, slow movement.",13,400,Design.MUTED);Design.space(body,14);
        LinearLayout title=Design.row(this);title.setMinimumHeight(Design.dp(this,42));title.addView(Design.text(this,"Sensitivity",15,600,Design.INK),new LinearLayout.LayoutParams(0,-2,1));title.addView(Design.iconButton(this,"info","About motion sensitivity",()->{if(explanation==null||!explanation.isShowing())explanation=SleepPicker.message(this,"Motion sensitivity","Low, Medium and High change how recorded motion is interpreted for smart wake-up and automatic settling detection. The setting applies to your next recording. Your saved raw motion readings do not change.");}),new LinearLayout.LayoutParams(Design.dp(this,42),Design.dp(this,42)));levelLabel=Design.text(this,savedProfile.calibrated&&!manualSelected?savedProfile.label():new MotionProfile(level).label(),13,400,Design.MUTED);title.addView(levelLabel);body.addView(title);SeekBar slider=new SeekBar(this);slider.setMax(2);slider.setProgress(level);slider.setContentDescription("Motion sensitivity");styleSlider(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(user){manualSelected=true;level=value;levelLabel.setText(new MotionProfile(level).label());update();}}public void onStartTrackingTouch(SeekBar b){manualSelected=true;levelLabel.setText(new MotionProfile(level).label());update();}public void onStopTrackingTouch(SeekBar b){}});body.addView(slider,new LinearLayout.LayoutParams(-1,Design.dp(this,48)));LinearLayout ends=Design.row(this);ends.addView(Design.text(this,"Low",12,400,Design.MUTED),new LinearLayout.LayoutParams(0,-2,1));ends.addView(Design.text(this,"High",12,400,Design.MUTED));body.addView(ends);Design.space(body,8);Design.item(body,"phone","Surface calibration",savedProfile.calibrated?"Calibrated · review or reset":"Measure still and gentle movement",()->{if(token==null)startActivityForResult(RecordUi.intent(this,MotionCalibrationActivity.class),793);});if(savedProfile.calibrated)Design.text(body,"Changing and saving a manual sensitivity clears the saved surface calibration.",12,400,Design.MUTED);
        LinearLayout footer=RecordUi.footer(body),buttons=Design.row(this),test=Design.col(this),save=Design.col(this);LinearLayout.LayoutParams a=new LinearLayout.LayoutParams(0,-2,1);a.rightMargin=Design.dp(this,5);buttons.addView(test,a);LinearLayout.LayoutParams b=new LinearLayout.LayoutParams(0,-2,1.4f);b.leftMargin=Design.dp(this,5);buttons.addView(save,b);footer.addView(buttons);Design.button(test,"Test again",false,this::test).setEnabled(token==null);use=Design.button(save,token==null?"Use this sensor":"Saving…",true,this::save);use.setTextSize(14*Appearance.scale(this));update();if(token!=null)RecordUi.enabled(body,false);
    }
    private void styleSlider(SeekBar bar){int height=Design.dp(this,8);android.graphics.drawable.GradientDrawable base=Design.shape(this,0xffe5dbea,20),fill=Design.shape(this,Design.VIOLET,20);base.setSize(1,height);fill.setSize(1,height);android.graphics.drawable.LayerDrawable track=new android.graphics.drawable.LayerDrawable(new android.graphics.drawable.Drawable[]{base,new android.graphics.drawable.ClipDrawable(fill,Gravity.START,android.graphics.drawable.ClipDrawable.HORIZONTAL)});track.setId(0,android.R.id.background);track.setId(1,android.R.id.progress);bar.setProgressTintList(null);bar.setProgressBackgroundTintList(null);bar.setProgressDrawable(track);bar.setMinHeight(height);bar.setMaxHeight(height);android.graphics.drawable.GradientDrawable thumb=Design.shape(this,Design.CREAM,20);thumb.setSize(Design.dp(this,26),Design.dp(this,26));thumb.setStroke(Design.dp(this,1),Design.VIOLET);bar.setThumbTintList(null);bar.setThumb(thumb);bar.setThumbOffset(Design.dp(this,13));bar.setSplitTrack(false);bar.setPadding(Design.dp(this,13),0,Design.dp(this,13),0);}
    private void test(){port.close();registered=false;preview.clear();unreliable=false;if(readFailed){update();return;}if(!port.available()){registrationError="No accelerometer is available on this device.";update();return;}try{registered=port.begin((time,x,y,z,accuracy)->{if(!resumed||!registered)return;unreliable=accuracy==android.hardware.SensorManager.SENSOR_STATUS_UNRELIABLE;if(!unreliable)preview.sample(time,x,y,z);});registrationError=registered?"":"The motion sensor could not be registered. Try again.";}catch(Exception e){port.close();registrationError="The motion sensor could not start. Try again.";}update();}
    private void update(){if(status==null)return;boolean recent=registered&&preview.recent(port.now());status.setText(!port.available()?"Unavailable":registered?"Active":"Not active");status.setTextColor(registered?0xff17833e:Design.MUTED);statusDot.setColor(registered?0xff2db24a:0xffa29c98);help.setText(!failure.isEmpty()?failure:!registrationError.isEmpty()?registrationError:unreliable?"Sensor accuracy is unreliable. Move gently and test again.":recent?"Signal detected · movement readings received.":"Waiting for motion readings. Missing data stays blank.");boolean signal=recent&&failure.isEmpty()&&registrationError.isEmpty()&&!unreliable;resultIcon.setVisibility(signal?View.VISIBLE:View.GONE);help.setTextColor(!failure.isEmpty()||!registrationError.isEmpty()?0xffa93919:Design.INK);if(chart!=null)chart.data(preview.bins(port.now(),savedProfile.calibrated&&!manualSelected?savedProfile:new MotionProfile(level)));if(use!=null){if(token==null)use.setText(savedProfile.calibrated&&!manualSelected?"Use calibrated sensor":"Use this sensor");boolean enabled=!readFailed&&registered&&token==null;use.setEnabled(enabled);use.setAlpha(enabled?1f:.45f);}}
    private void save(){if(token!=null||!registered||readFailed)return;if(savedProfile.calibrated&&!manualSelected){setResult(RESULT_OK);finish();return;}token=java.util.UUID.randomUUID().toString();failure="";render();observe();}
    private void observe(){if(!resumed||token==null)return;int value=level,prior=expected;MotionSettings.Factory scope=settings;MotionSettings.Version version=settingsVersion;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{if(version!=null)MotionSettings.save(scope.open(app),value,version);else MotionSettings.save(scope.open(app),value,prior);return null;});if(!operation.done){handler.postDelayed(poll,75);return;}PlanOperations.forget(token);token=null;if(operation.error==null){setResult(RESULT_OK);finish();}else{failure=operation.error;render();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==793&&result==RESULT_OK){try{SharedPreferences prefs=settings.open(this);settingsVersion=new MotionSettings.Version(prefs);savedProfile=MotionSettings.read(prefs);level=expected=savedProfile.level;manualSelected=false;readFailed=false;failure="";}catch(RuntimeException unavailable){readFailed=true;failure="Motion settings could not be read. Reopen before saving.";}render();}}
    private void back(){if(token==null)finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("manualSelected",manualSelected);state.putInt("level",level);state.putInt("expected",expected);state.putString("token",token);state.putString("failure",failure);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(explanation!=null)explanation.dismiss();port.close();super.onDestroy();}
}
